SELECT gen_random_uuid(), q.id, 1, '[{"type": "tldr", "title": "TL;DR", "content": "Route reflectors forward routes to clients without modifying NEXT_HOP, AS_PATH, or LOCAL_PREF. They add cluster ID and originator ID."}, {"type": "tldr", "title": "Коротко", "content": "Route reflectors передают маршруты клиентам без изменения NEXT_HOP, AS_PATH или LOCAL_PREF.", "lang": "ru"}, {"type": "distractor_breakdown", "title": "Разбор вариантов", "content": "**B** - Неверно.\n\n**C** - Неверно.\n\n**D** - Неверно."}]', 'Route reflectors передают маршруты клиентам без изменения NEXT_HOP, AS_PATH или LOCAL_PREF.', NOW()
