INSERT INTO explanations (id, question_id, version, sections, summary, created_at)
SELECT gen_random_uuid(), q.id, 1, '[{"type": "tldr", "title": "TL;DR", "content": "CLUSTER_LIST prevents routing loops between route reflectors. When a RR sees its own cluster ID in the CLUSTER_LIST, it ignores the route."}, {"type": "tldr", "title": "Коротко", "content": "CLUSTER_LIST предотвращает петли маршрутизации между route reflector. Когда RR видит свой cluster ID — игнорирует маршрут.", "lang": "ru"}, {"type": "distractor_breakdown", "title": "Разбор вариантов", "content": "**B** - Неверно.\n\n**C** - Неверно.\n\n**D** - Неверно."}]', 'CLUSTER_LIST предотвращает петли маршрутизации между route reflector. Когда RR видит свой cluster ID — игнорирует маршрут.', NOW()
