FROM questions q WHERE q.content_hash = '4582793909a33737_gen_v2' AND NOT EXISTS (SELECT 1 FROM explanations e WHERE e.question_id = q.id);
INSERT INTO explanations (id, question_id, version, sections, summary, created_at)
SELECT gen_random_uuid(), q.id, 1, '[{"type": "tldr", "title": "TL;DR", "content": "MAC Mobility is signaled via an extended community with a sequence number. The PE with the higher sequence wins. Duplicate MAC detection can also be configured (Variant 10)."}, {"type": "tldr", "title": "Коротко", "content": "MAC Mobility сигнализируется extended community с номером последовательности. PE с большим номером побеждает (Вариант 10).", "lang": "ru"}, {"type": "distractor_breakdown", "title": "Разбор вариантов", "content": "**B** - Неверно.\n\n**C** - Неверно.\n\n**D** - Неверно."}]', 'MAC Mobility сигнализируется extended community с номером последовательности. PE с большим номером побеждает (Вариант 10).', NOW()
FROM questions q WHERE q.content_hash = '722a3bda288ee326_gen_v2' AND NOT EXISTS (SELECT 1 FROM explanations e WHERE e.question_id = q.id);
INSERT INTO explanations (id, question_id, version, sections, summary, created_at)
SELECT gen_random_uuid(), q.id, 1, '[{"type": "tldr", "title": "TL;DR", "content": "Route Type 4 is used for DF election in multi-homed segments. PEs advertise the same ESI; the PE with the highest IP is elected DF for each VLAN."}, {"type": "tldr", "title": "Коротко", "content": "Route Type 4 используется для DF election в multi-homed сегментах. PE рекламируют одинаковый ESI; PE с высшим IP становится DF.", "lang": "ru"}, {"type": "distractor_breakdown", "title": "Разбор вариантов", "content": "**B** - Неверно.\n\n**C** - Неверно.\n\n**D** - Неверно."}]', 'Route Type 4 используется для DF election в multi-homed сегментах. PE рекламируют одинаковый ESI; PE с высшим IP становится DF.', NOW()
